// x86-64 Scaled Indexing:
// Base + (Index * Scale) + Displacement

int array[10]; // Scale = 4 (for int)
long index = 5;

// C access: array[index]
int val = array[index];

// Assembly Equivalent (conceptual):
// BaseReg = &array[0]
// IndexReg = index

// Efficient Array Element Load (Scale = 4)
// movl (%BaseReg, %IndexReg, 4), %eax

// Supported Scale Factors: 1, 2, 4, 8

// Example: Load data 8 bytes past the base pointer
// movq 8(%rbx), %rax // Disp=8, Index=0, Scale=1

// Example: Load element from a struct array (Scale = 16)
// movq (%BaseReg, %IndexReg, 16), %rax
